  Plaintext c5("c5");
  Ciphertext z = x * alpha;
  Ciphertext u = z * z;
  Ciphertext u2 = u + u;
  Ciphertext w = u2 + u2;
  Ciphertext ww = w * w;
  Ciphertext w2 = w + w;
  Ciphertext w5 = (w2 + w2) + w;
  Ciphertext q = ww - w5;
  Ciphertext r = w * c3 + q * c5;
  Ciphertext zc1 = z * c1;
  Ciphertext zc3 = z * c3;
  Ciphertext zc5 = z * c5;
  Ciphertext zc3x3 = (zc3 + zc3) + zc3;
